//! Centralized lore tuning constants.
#![allow(dead_code)]
pub const FIRST_RELIC_AUTHORITY_Q:i32=10000; pub const ECHO_RELIC_AUTHORITY_Q:i32=3500; pub const SUPERIOR_DEXTER_BONUS_Q:i32=5000; pub const QUINCUNX_BASE_PENALTY_Q:i32=5000; pub const YOD_BASE_PRESSURE_Q:i32=6000; pub const FINGER_OF_GOD_PRESSURE_Q:i32=7500; pub const CHARGE_HEAD_CUT_DOWNGRADE_Q:i32=7500; pub const NAME_SHEAR_DAMAGE_Q:i32=4000; pub const WITNESS_CHAIN_PROTECTION_Q:i32=5000; pub const DEATH_SCAR_VISIBILITY_Q:i32=4000; pub const PUZZLE_SCAR_VISIBILITY_Q:i32=6500; pub const GEAR_CHARGE_DEATH_TITHE_Q:i32=1000; pub const VOWLESS_SUPPRESSION_Q:i32=10000;
pub fn echo_power_q(first_power_q:i32,difficulty:u32)->i32{let base=first_power_q/3;let bonus=(first_power_q*difficulty.min(1000)as i32)/10000;(base+bonus).min(first_power_q*3/4)} pub fn charge_decay_per_hour_q(tier:u8)->i32{match tier{0=>100,1=>75,2=>50,3=>25,_=>10}} pub fn zone_difficulty_scale_q(difficulty:u32)->i32{10000+difficulty.min(10000)as i32*50}
